package com.smarthub.plus;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.*;

/** Foreground-only, token-protected LAN upload. Never serves user files or credentials. */
public final class ChlImportServer implements AutoCloseable {
 public interface Importer {String accept(InputStream input)throws Exception;}
 private final ServerSocket server;private final Importer importer;private final String route;private volatile boolean running=true;private volatile Socket active;private final long until=System.currentTimeMillis()+600000;
 public ChlImportServer(Importer importer)throws IOException{this.importer=importer;byte[] random=new byte[8];new SecureRandom().nextBytes(random);StringBuilder token=new StringBuilder();for(byte b:random)token.append(String.format(Locale.ROOT,"%02x",b&255));route="/chl/"+token;server=new ServerSocket(0);server.setSoTimeout(1000);Thread t=new Thread(this::serve,"iraqhub-chl-import");t.setDaemon(true);t.start();}
 public String localAddress()throws SocketException{Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all.hasMoreElements()){NetworkInterface n=all.nextElement();if(!n.isUp()||n.isLoopback())continue;Enumeration<InetAddress> addresses=n.getInetAddresses();while(addresses.hasMoreElements()){InetAddress a=addresses.nextElement();if(a instanceof Inet4Address&&a.isSiteLocalAddress())return "http://"+a.getHostAddress()+":"+server.getLocalPort()+route;}}return "";}
 String loopbackAddress(){return "http://127.0.0.1:"+server.getLocalPort()+route;}
 private static String line(InputStream in,int[] total)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();int b;while((b=in.read())!=-1){if(++total[0]>8192)throw new IOException("Header too long");if(b=='\n')return out.toString("US-ASCII").replace("\r","");out.write(b);}throw new EOFException();}
 private void serve(){while(running&&System.currentTimeMillis()<until){try(Socket socket=server.accept()){active=socket;if(!running)return;if(!socket.getInetAddress().isSiteLocalAddress()&&!socket.getInetAddress().isLoopbackAddress())continue;socket.setSoTimeout(15000);handle(socket);}catch(SocketTimeoutException ignored){}catch(Exception ignored){}finally{active=null;}}close();}
 private void handle(Socket socket)throws IOException{
  InputStream in=new BufferedInputStream(socket.getInputStream());int[] total={0};String first=line(in,total);String[] request=first.split(" ");Map<String,String> headers=new HashMap<>();String h;while(!(h=line(in,total)).isEmpty()){int p=h.indexOf(':');if(p<1)throw new IOException("Bad header");String key=h.substring(0,p).trim().toLowerCase(Locale.ROOT);if(headers.put(key,h.substring(p+1).trim())!=null)throw new IOException("Duplicate header");}
  if(request.length!=3||!request[1].equals(route)){reply(socket,404,"Not found","text/plain");return;}
  if(request[0].equals("GET")){reply(socket,200,page(),"text/html");return;}
  String origin=headers.get("origin"),host=headers.get("host");
  if(!request[0].equals("POST")||origin!=null&&!origin.equals("http://"+host)){reply(socket,403,"Request rejected","text/plain");return;}
  long length;try{length=Long.parseLong(headers.getOrDefault("content-length","-1"));}catch(Exception e){length=-1;}
  if(length<1||length>16*1024*1024||headers.containsKey("transfer-encoding")||!"application/octet-stream".equals(headers.get("content-type"))){reply(socket,413,"Select a CHL file up to 16 MB","text/plain");return;}
  final long size=length;InputStream limited=new InputStream(){long remaining=size;public int read()throws IOException{if(remaining==0)return -1;int b=in.read();if(b<0)throw new EOFException();remaining--;return b;}public int read(byte[] b,int off,int len)throws IOException{if(remaining==0)return -1;int n=in.read(b,off,(int)Math.min(remaining,len));if(n<0)throw new EOFException();remaining-=n;return n;}};
  try{String result=importer.accept(limited);reply(socket,200,result,"text/plain");}catch(Exception e){reply(socket,422,"لم يُقبل الملف؛ بقيت البيانات السابقة. تحقق من صيغة CHL.","text/plain");}
 }
 private static String page(){return "<!doctype html><html lang='ar' dir='rtl'><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>IRAQhub CHL</title><body style='font:20px sans-serif;max-width:700px;margin:40px auto;padding:20px'><h1>استيراد CHL إلى IRAQhub</h1><p>اختر ملف القنوات من جهازك. يُستورد للتعرف على القنوات والشعارات دون تعديل قائمة الرسيفر.</p><input id='file' type='file' accept='.chl'><button id='send'>استيراد الملف</button><p id='status'></p><script>document.getElementById('send').onclick=async()=>{const b=document.getElementById('send'),s=document.getElementById('status'),f=document.getElementById('file').files[0];if(!f||f.size>16777216){s.textContent='اختر ملف CHL حتى 16 MB';return;}b.disabled=true;s.textContent='جارٍ الاستيراد…';try{const r=await fetch(location.pathname,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:f});s.textContent=await r.text();}catch(e){s.textContent='تعذر الاتصال؛ اترك صفحة الاستقبال مفتوحة على التلفزيون';}b.disabled=false;};</script></body></html>";}
 private static void reply(Socket socket,int code,String text,String type)throws IOException{byte[] body=text.getBytes(StandardCharsets.UTF_8);String header="HTTP/1.1 "+code+" "+(code==200?"OK":"Rejected")+"\r\nContent-Type: "+type+"; charset=utf-8\r\nContent-Length: "+body.length+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nContent-Security-Policy: default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'\r\nConnection: close\r\n\r\n";OutputStream out=socket.getOutputStream();out.write(header.getBytes(StandardCharsets.US_ASCII));out.write(body);out.flush();}
 @Override public void close(){running=false;Socket current=active;if(current!=null)try{current.close();}catch(IOException ignored){}try{server.close();}catch(IOException ignored){}}
}
